const fields={speed:'속도 (m/s)',gear:'기어',targetGear:'목표 기어',engineRPM:'엔진 RPM',engineTorque:'엔진 토크 (N·m)',shiftRemaining:'변속 남은 시간 (s)'};
export function vehicleDebugPage(object,{offset=0,limit=64}={}){if(!Number.isInteger(offset)||offset<0||!Number.isInteger(limit)||limit<1||limit>256)throw Error('차량 진단 페이지를 확인하세요.');const s=object?.gameplayDebug?.vehicle;if(!s)return{ready:false,total:0,items:[]};return{ready:true,owner:object.id,driveModel:s.driveModel,...Object.fromEntries(Object.keys(fields).map(k=>[k,s[k]])),shifting:s.shifting,total:s.wheels.length,offset,items:structuredClone(s.wheels.slice(offset,offset+limit)),nextOffset:offset+limit<s.wheels.length?offset+limit:null};}
export function vehicleReadout(state={}){return '<div class="vehicle-readout">'+Object.entries(fields).map(([key,label])=>'<div class="component-property"><label>'+label+'</label><output data-vehicle-stat="'+key+'">'+format(state[key])+'</output></div>').join('')+'</div>';}
function format(value){return Number.isFinite(value)?String(Number(value.toFixed(2))):'—';}
export function updateVehicleReadout(root,object){const state=object?.gameplayDebug?.vehicle;if(!state)return;for(const e of root.querySelectorAll('[data-vehicle-stat]')){const value=format(state[e.dataset.vehicleStat]);if(e.textContent!==value)e.textContent=value;}}
